  for (rp = res; rp; rp = rp->ai_next) {
    sock_t fd = bindInternal(rp->ai_family, rp->ai_socktype, rp->ai_protocol,
                             rp->ai_addr, rp->ai_addrlen, error);
    if (fd != (sock_t)-1) {
      return fd;
    }
  }
  return -1;
}

